// P2P VOICES — the provider-independent contract (owner brief 2026-11-18). Every speech provider is an adapter
// behind this one interface; P2P Listen (the app's single player) never sees a provider's own response format.
//
// Hard rules encoded here:
//   • ElevenLabs is CATALOGUE + PREVIEW ONLY — its adapter has no `synthesize` at all, so no code path can
//     generate ElevenLabs audio or spend ElevenLabs credits. Official Kingdom Stories narration is generated by
//     the owner outside P2P and uploaded through the owner-only workflow (routes/narrationsAdmin.ts).
//   • Bible content is never synthesised by any provider (see ELIGIBLE_KINDS in synth.ts).
//   • A provider is `enabled` only when its server-side credentials exist; specialist (Igbo) providers also need
//     an explicit verification flag — advertising a language is not enough.
//   • Secrets live only in the server environment; they never appear in responses, logs or errors.

export type ProviderId = "azure" | "google" | "elevenlabs" | "spitch" | "naijalingo" | "naijaspeech";
export type Presentation = "female" | "male";
export type Characteristic = "warm" | "deep" | "gentle" | "expressive" | "conversational" | "narrator" | "calm" | "clear";
export const CHARACTERISTICS: Characteristic[] = ["warm", "deep", "gentle", "expressive", "conversational", "narrator", "calm", "clear"];

/** One voice, normalised. `id` is P2P's internal id: "<provider>:<providerVoiceId>". */
export interface Voice {
  id: string;
  provider: ProviderId;
  providerVoiceId: string;
  name: string;
  /** BCP-47 base language ("en", "ig") and full locale ("en-NG"). */
  language: string;
  languageName: string;
  locale: string;
  /** Accent / variety derived from the LOCALE the provider reports (never from the voice's name). */
  accent: string;
  /** Only when the provider supplies it; NEUTRAL / unspecified → null (never guessed). */
  presentation: Presentation | null;
  /** Only descriptors the provider's own metadata contains. */
  characteristics: Characteristic[];
  model: string | null;
  /** Provider preview URL (ElevenLabs), or "generate" = a short controlled sample can be synthesised. */
  preview: { kind: "url"; url: string } | { kind: "generate" } | null;
  /** Can P2P synthesise eligible content with it? (false for ElevenLabs — catalogue only.) */
  canSynthesize: boolean;
  status: "available" | "unavailable";
  /** Where the voice came from and when (the provider account's own list — not a marketing catalogue). */
  source: string;
  refreshedAt: string;
}

export interface ProviderPolicy {
  /** May P2P store generated audio and serve it again? */
  cacheAllowed: boolean;
  /** May the phone keep it for offline listening? */
  offlineAllowed: boolean;
  /** How long stored audio may be kept (days); null = no limit stated in the provider's terms for customer output. */
  retentionDays: number | null;
  note: string;
}

export interface ProviderStatus {
  id: ProviderId;
  name: string;
  role: string;
  enabled: boolean;
  /** Why it is off (no credentials, not verified…) — safe to show to admins; never contains a secret. */
  reason: string | null;
  policy: ProviderPolicy;
}

export interface SynthesisResult { audio: Buffer; contentType: string; characters: number }

export interface VoiceProvider {
  id: ProviderId;
  name: string;
  role: string;
  policy: ProviderPolicy;
  /** Credentials present (and, for specialists, verified). */
  status(): { enabled: boolean; reason: string | null };
  /** The voices the AUTHENTICATED account can use (dynamic — never a hard-coded list). */
  listVoices(signal: AbortSignal): Promise<Voice[]>;
  /** Absent for catalogue-only providers (ElevenLabs). */
  synthesize?(text: string, voice: Voice, signal: AbortSignal): Promise<SynthesisResult>;
}

/** A provider error that is safe to keep in logs and admin usage records (no secret, no content). */
export class ProviderError extends Error {
  constructor(public provider: ProviderId, public code: "unconfigured" | "timeout" | "rate_limited" | "rejected" | "unavailable" | "bad_response", message: string, public status?: number) {
    super(message);
  }
}

export async function fetchWithTimeout(url: string, init: RequestInit & { timeoutMs?: number; provider: ProviderId; signal?: AbortSignal }): Promise<Response> {
  const ctl = new AbortController();
  const timer = setTimeout(() => ctl.abort(), init.timeoutMs ?? 15_000);
  const outer = init.signal;
  if (outer) outer.addEventListener("abort", () => ctl.abort(), { once: true });
  try {
    const r = await fetch(url, { ...init, signal: ctl.signal });
    if (r.status === 429) throw new ProviderError(init.provider, "rate_limited", "The provider's rate limit was reached.", 429);
    if (r.status === 401 || r.status === 403) throw new ProviderError(init.provider, "rejected", "The provider rejected P2P's credentials.", r.status);
    if (r.status >= 500) throw new ProviderError(init.provider, "unavailable", "The provider is temporarily unavailable.", r.status);
    if (!r.ok) throw new ProviderError(init.provider, "bad_response", `The provider answered ${r.status}.`, r.status);
    return r;
  } catch (e) {
    if (e instanceof ProviderError) throw e;
    if ((e as Error)?.name === "AbortError") throw new ProviderError(init.provider, "timeout", "The provider did not answer in time.");
    throw new ProviderError(init.provider, "unavailable", "The provider could not be reached.");
  } finally { clearTimeout(timer); }
}

// ── Locale → language name and accent (from the LOCALE only) ─────────────────────────────────────────────────
const languageNames = new Intl.DisplayNames(["en"], { type: "language" });
const regionNames = new Intl.DisplayNames(["en"], { type: "region" });
/** English varieties people recognise by an adjective; any other region is shown as "English (Region)". */
const ENGLISH_ADJ: Record<string, string> = { GB: "British English", US: "American English", NG: "Nigerian English", ZA: "South African English", KE: "Kenyan English",
  GH: "Ghanaian English", UG: "Ugandan English", TZ: "Tanzanian English", AU: "Australian English", CA: "Canadian English", IE: "Irish English", IN: "Indian English",
  NZ: "New Zealand English", SG: "Singaporean English", PH: "Philippine English", HK: "Hong Kong English" };
export function describeLocale(locale: string): { language: string; languageName: string; locale: string; accent: string } {
  const parts = String(locale).replace("_", "-").split("-").filter(Boolean);
  const language = (parts[0] ?? "").toLowerCase();
  const region = parts.find((p, i) => i > 0 && /^[A-Z]{2}$|^\d{3}$/i.test(p) && p.length === 2)?.toUpperCase() ?? null;
  const norm = region ? `${language}-${region}` : language;
  let languageName = language;
  try { languageName = languageNames.of(language) ?? language; } catch { /* unknown code: keep it */ }
  let accent = languageName;
  if (region) {
    if (language === "en" && ENGLISH_ADJ[region]) accent = ENGLISH_ADJ[region];
    else { let r = region; try { r = regionNames.of(region) ?? region; } catch { /* keep code */ } accent = `${languageName} (${r})`; }
  }
  return { language, languageName, locale: norm, accent };
}

/** Provider descriptors → P2P characteristics, by the provider's OWN words only (no inference from names). */
export function characteristicsFrom(words: (string | null | undefined)[]): Characteristic[] {
  const out = new Set<Characteristic>();
  for (const raw of words) {
    const w = String(raw ?? "").toLowerCase();
    if (!w) continue;
    for (const c of CHARACTERISTICS) if (new RegExp(`\\b${c}\\b`).test(w)) out.add(c);
    if (/\bnarrat(ion|or|ive)|audiobook/.test(w)) out.add("narrator");
    if (/\bconversation(al)?\b|\bchat\b/.test(w)) out.add("conversational");
  }
  return [...out];
}
/** Child voices are not offered at this stage (owner): any provider metadata that marks a voice as a child's. */
export const isChildVoice = (words: (string | null | undefined)[]) => words.some((w) => /\b(child|children|kid|kids|boy|girl)\b/i.test(String(w ?? "")));
